<script>
 import { Camera, Sparkles, Upload, Copy, Check, ArrowRight, Image, Film, RefreshCw, Plus, X, ShieldCheck } from 'lucide-svelte';
 import { composePrompts, wordCount, validateScene, scopedAssets, approvedSceneAsset } from '../visual-model.js';
 import { importImage } from '../visual-store.js';
 import GenerationStudio from './GenerationStudio.svelte';
 let { scene=$bindable(), storyId, characters=[], locations=[], assets=[], previous=null, onassetschange, onlocation, onnext, notify }=$props();
 let promptTab=$state('image'), error=$state(''), uploading=$state(false), providerNotice=$state(''), createLocation=$state(false), locationName=$state(''), locationDescription=$state('');
 let generationOpen=$state(false),generationKind=$state('scene');
 let draftPrompts=$derived(composePrompts(scene,characters,locations,previous,assets));
 let effectivePrompt=$derived(scene.promptOverrides?.[promptTab] ?? draftPrompts[promptTab]);
 let versions=$derived(scopedAssets(assets,'scene',scene.id,storyId));
 let approved=$derived(approvedSceneAsset(scene,storyId,assets));
 let currentPlace=$derived(locations.find(l=>l.id===scene.locationId));
 let selectedCast=$derived(characters.filter(c=>scene.characterIds?.includes(c.id)));
 let missingRefs=$derived(selectedCast.filter(c=>!assets.some(a=>a.type==='character'&&a.ownerId===c.id&&a.approved)).map(c=>c.name));
 const tabs=[['image','Image prompt'],['imageToVideo','Image to video'],['textToVideo','Text to video']];
 function editPrompt(value){scene.promptOverrides={...scene.promptOverrides,[promptTab]:value};}
 function toggleCharacter(id){scene.characterIds=scene.characterIds?.includes(id)?scene.characterIds.filter(x=>x!==id):[...(scene.characterIds||[]),id];}
 function save(finalize=false,next=false){
   error=finalize?validateScene(scene):'';if(error)return;
   scene.status=finalize?'Ready for review':'Draft';scene.finalized=finalize;scene.updatedAt=new Date().toISOString();notify(finalize?'Scene finalized and saved on this device':'Draft saved on this device');if(next)onnext();
 }
 function requestGeneration(kind){
   error=validateScene(scene);if(error)return;
   if(kind==='video'&&!approved){error='Approve a scene image before creating image-to-video.';return;}
   generationKind=kind==='image'?'scene':'image-to-video';generationOpen=true;
 }
 async function upload(event){
   const file=event.currentTarget.files?.[0];if(!file)return;error=validateScene(scene);if(error){event.currentTarget.value='';return;}uploading=true;
   try{await importImage(file,{type:'scene',ownerId:scene.id,storyId,prompt:scene.promptOverrides?.image??draftPrompts.image,camera:scene.camera||'Eye-level medium wide',characterIds:[...(scene.characterIds||[])],locationId:scene.locationId,referenceIds:assets.filter(a=>a.approved&&((a.type==='character'&&scene.characterIds?.includes(a.ownerId))||(a.type==='location'&&a.ownerId===scene.locationId))).map(a=>a.id)});await onassetschange();notify('New image version saved. Choose Approve to use it.');}catch(e){error=e.message;}finally{uploading=false;event.target.value='';}
 }
 function addLocation(){if(!locationName.trim()||!locationDescription.trim())return;const l=onlocation(locationName.trim(),locationDescription.trim());scene.locationId=l.id;scene.location=l.name;createLocation=false;locationName='';locationDescription='';}
 async function copy(text){try{await navigator.clipboard.writeText(text);notify('Prompt copied');}catch{error='Clipboard unavailable. Select and copy the prompt text.';}}
</script>

<section class="director" aria-label="AI Scene Director">
 <header class="director-header"><div><span class="eyebrow"><Sparkles size={14}/> AI SCENE DIRECTOR</span><h2>Direct this moment.</h2><p>Cast the scene. Set the world. Tell us what happens.</p></div><span class="director-mode">Local prompt composer <i></i></span></header>
 <div class="director-steps"><span class="active">01 Cast & setting</span><span>02 Write & direct</span><span>03 Review & create</span></div>
 <div class="director-layout"><div class="director-inputs">
  <section class="director-section"><div class="director-section-title"><h3>Saved characters</h3><small>{scene.characterIds?.length||0} selected</small></div><p>Select the people who appear in this moment. Their identities carry into every prompt.</p><div class="cast-selector">{#each characters as c}<button class:chosen={scene.characterIds?.includes(c.id)} aria-pressed={!!scene.characterIds?.includes(c.id)} onclick={()=>toggleCharacter(c.id)}>{#if c.image}<img src={c.image} alt=""/>{:else}<span class="cast-initials">{c.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span>{/if}<span><strong>{c.name}</strong><small>{c.projectTitle}</small></span>{#if scene.characterIds?.includes(c.id)}<Check size={16}/>{/if}</button>{/each}</div></section>
  <section class="director-section"><div class="director-section-title"><h3>Saved location</h3><button class="text-button" onclick={()=>createLocation=!createLocation}><Plus size={14}/> New location</button></div><label class="director-field">Where does this happen?<select aria-label="Scene saved location" value={scene.locationId||''} onchange={e=>{scene.locationId=e.currentTarget.value;scene.location=locations.find(l=>l.id===scene.locationId)?.name||'';}}><option value="">Choose a saved location</option>{#each locations as l}<option value={l.id}>{l.name} · {l.projectTitle||'Your location'}</option>{/each}</select></label>{#if currentPlace}<p class="location-context">{currentPlace.description}</p>{/if}{#if createLocation}<div class="inline-location"><label class="director-field">Location name<input bind:value={locationName}/></label><label class="director-field">Visual description<textarea bind:value={locationDescription} placeholder="Architecture, geography, materials, landmarks and light"></textarea></label><button class="button primary" onclick={addLocation} disabled={!locationName.trim()||!locationDescription.trim()}>Save location</button></div>{/if}</section>
  <section class="director-section"><div class="director-section-title"><h3>The story moment</h3><strong class:word-ready={wordCount(scene.text)>=100} class="word-counter" aria-live="polite">{wordCount(scene.text)} / 100 words</strong></div><label class="director-field">Scene title<input bind:value={scene.title} placeholder="Give this moment a name"/></label><label class="director-field">Scene description <textarea class="moment-description" aria-label="Scene description" bind:value={scene.text} placeholder="Describe the exact action, discovery or decision. What changes for the characters? Write at least 100 words."></textarea></label><p>Drafts save while you write. Finalizing and Next Moment require 100 words in this description.</p>
   <div class="direction-grid"><label class="director-field">Actions & interactions<textarea bind:value={scene.actions} placeholder="Who does what, with which props?"></textarea></label><label class="director-field">Emotions & expressions<textarea bind:value={scene.emotions} placeholder="A restrained smile, doubt, recognition…"></textarea></label><label class="director-field">Dialogue<textarea bind:value={scene.dialogue} placeholder="Optional spoken lines"></textarea></label><label class="director-field">Lighting & atmosphere<textarea bind:value={scene.atmosphere} placeholder="Cold dawn through high windows, dust in the air…"></textarea></label></div>
   <div class="direction-grid"><label class="director-field">Camera angle<select bind:value={scene.camera}><option value={undefined}>Eye-level medium wide</option><option>Wide establishing shot</option><option>Over the shoulder</option><option>Low angle</option><option>High angle</option><option>Close-up</option><option>Extreme close-up</option><option>Bird’s-eye view</option></select></label><label class="director-field">Lens<select bind:value={scene.lens}><option value={undefined}>35mm</option><option>24mm</option><option>50mm</option><option>85mm</option><option>100mm macro</option></select></label><label class="director-field">Camera movement<select bind:value={scene.cameraMove}><option value={undefined}>slow dolly in</option><option>locked off</option><option>gentle handheld</option><option>lateral tracking</option><option>slow orbit</option><option>crane reveal</option></select></label></div>
   <details class="director-continuity"><summary>Continuity from the previous moment</summary><p>{previous?`${previous.title}: ${previous.text.slice(-650)}`:'Opening scene. Establish the visual language for this story.'}</p><label class="director-field">Continuity notes<textarea bind:value={scene.continuity} placeholder="Costume, props, physical state, time of day, or an explicit continuity override"></textarea></label></details>
  </section>
 </div><div class="director-output">
  <section class="director-section prompt-composer"><div class="director-section-title"><h3><Sparkles size={16}/> Prompt studio</h3><span class="live-tag">Live · no credits used</span></div><p>Structured suggestions combine your scene, saved identities, setting and continuity. They update locally as you type.</p><div class="director-tabs" role="tablist" aria-label="Generation prompt type">{#each tabs as [key,label]}<button role="tab" aria-selected={promptTab===key} class:active={promptTab===key} onclick={()=>promptTab=key}>{label}</button>{/each}</div><label class="director-field">{tabs.find(t=>t[0]===promptTab)?.[1]}<textarea class="prompt-editor" aria-label="Editable generation prompt" value={effectivePrompt} oninput={e=>editPrompt(e.currentTarget.value)}></textarea></label><div class="prompt-actions"><button class="button secondary" onclick={()=>copy(effectivePrompt)}><Copy size={14}/> Copy prompt</button><button class="text-button" onclick={()=>{scene.promptOverrides={...scene.promptOverrides,[promptTab]:undefined};notify('Prompt rebuilt from current direction');}}><RefreshCw size={14}/> Rebuild prompt</button></div>{#if scene.promptOverrides?.[promptTab]!==undefined}<p class="inline-note">Manual edit preserved. Rebuild to include later scene changes.</p>{/if}</section>
  <section class="director-section visual-production"><div class="director-section-title"><h3><Camera size={16}/> Scene image</h3><span class="subtle-badge">{versions.length} versions</span></div>{#if approved}<img class="approved-scene-image" src={approved.url} alt={`Approved scene image: ${scene.title}`}/><div class="approved-label"><ShieldCheck size={14}/> Approved image · {approved.id.slice(0,8)}</div>{:else}<div class="scene-image-empty"><Image size={32}/><h4>Make this moment visible.</h4><p>Your scene image belongs here. Character sheets and location references are never used as scene images.</p></div>{/if}
  {#if missingRefs.length}<p class="reference-warning">Identity references needed: {missingRefs.join(', ')}. Add and approve sheets in the Character Library.</p>{/if}
  <div class="production-actions"><button class="button primary" onclick={()=>requestGeneration('image')}><Sparkles size={15}/>{versions.length?'Regenerate Image':'Generate Image'}</button><label class="button secondary upload-control"><Upload size={14}/>{uploading?'Saving image…':'Import image version'}<input type="file" accept="image/png,image/jpeg,image/webp" disabled={uploading} onchange={upload}/></label></div><p class="inline-note">Higgsfield is not connected. Review settings in the mock studio. Editing, selecting and saving never request generation.</p>
  {#if providerNotice}<div class="provider-notice" role="status"><strong>Connect a generation provider</strong><p>{providerNotice}</p><button class="text-button" onclick={()=>providerNotice=''}>Dismiss <X size={13}/></button></div>{/if}
  {#if versions.length}<div class="scene-version-list">{#each versions.toReversed() as v,i}<article class:approved={scene.approvedImageId===v.id}><img src={v.url} alt={`Scene image version ${versions.length-i}`}/><div><strong>Version {versions.length-i}</strong><small>{new Date(v.createdAt).toLocaleString()} · {v.source}</small><small>{v.camera}</small><details><summary>Saved prompt & reference IDs</summary><p>{v.prompt}</p><p>Character IDs: {v.characterIds?.join(', ')}. Location ID: {v.locationId}. Reference IDs: {v.referenceIds?.join(', ')||'None supplied'}.</p></details><div class="version-actions"><button class="button secondary" onclick={()=>{scene.approvedImageId=v.id;notify('Approved image selected for this scene only');}}>{scene.approvedImageId===v.id?'Approved':'Approve this version'}</button><a href={v.url} download={`${storyId}-scene-${scene.id}-v${versions.length-i}.png`}>Download</a></div></div></article>{/each}</div>{/if}
  </section>
  <section class="director-section"><div class="director-section-title"><h3><Film size={16}/> Animate the moment</h3></div>{#if approved}<div class="video-source"><img src={approved.url} alt="Exact starting frame for video"/><span><strong>Exact starting frame</strong><small>Image {approved.id.slice(0,8)} · {storyId} / scene {scene.id}</small></span></div>{:else}<p>Approve a scene image to use it as the exact first frame.</p>{/if}<div class="production-actions"><button class="button secondary" disabled={!approved} onclick={()=>{scene.videoBrief={sourceAssetId:approved.id,prompt:scene.promptOverrides?.imageToVideo??draftPrompts.imageToVideo,createdAt:new Date().toISOString()};promptTab='imageToVideo';requestGeneration('video');}}><Film size={14}/> Image to video</button><button class="text-button" onclick={()=>{promptTab='textToVideo';generationKind='text-to-video';generationOpen=true;}}>Text to video <ArrowRight size={14}/></button></div>{#if scene.videoBrief}<p class="inline-note">Saved video brief uses image {scene.videoBrief.sourceAssetId.slice(0,8)}. Other image approvals do not change this saved starting frame.</p>{/if}</section>
 {#if generationOpen}{#key generationKind}<GenerationStudio {storyId} {scene} kind={generationKind} prompt={generationKind==='scene'?(scene.promptOverrides?.image??draftPrompts.image):generationKind==='image-to-video'?(scene.promptOverrides?.imageToVideo??draftPrompts.imageToVideo):(scene.promptOverrides?.textToVideo??draftPrompts.textToVideo)} {assets} {onassetschange} {notify}/>{/key}{/if}</div></div>
 {#if error}<div class="director-error" role="alert">{error}</div>{/if}<footer class="director-save"><span><ShieldCheck size={15}/> Saved on this device. Export your media backup regularly.</span><div><button class="button secondary" onclick={()=>save()}>Save draft</button><button class="button secondary" onclick={()=>save(true)}>Save Scene</button><button class="button primary" onclick={()=>save(true,true)}>Next Moment <ArrowRight size={15}/></button></div></footer>
</section>
